#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 16

// ------------------------------------------------------------------
// Kernel: batched matrix multiplication for fp16 tensors
// ------------------------------------------------------------------
extern "C" __global__
void bmm_fp16_kernel(const half* __restrict__ A,
                     const half* __restrict__ B,
                     half* __restrict__ C,
                     int batch,
                     int M, int N, int K) {
    // batch index
    int b = blockIdx.z;
    if (b >= batch) return;

    // tile coordinates
    int tile_i = blockIdx.y;   // rows
    int tile_j = blockIdx.x;   // cols

    // thread coordinates inside a tile
    int ti = threadIdx.y;      // 0..TILE_M-1
    int tj = threadIdx.x;      // 0..TILE_N-1

    // global row / col for this thread
    int row = tile_i * TILE_M + ti;
    int col = tile_j * TILE_N + tj;

    // accumulator in fp32
    float acc = 0.0f;

    // shared memory buffers
    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    // number of K‑tiles
    int num_tiles_k = (K + TILE_K - 1) / TILE_K;

    for (int tile_k = 0; tile_k < num_tiles_k; ++tile_k) {
        // -------------------- load A tile --------------------
        int a_row = row;
        int a_col = tile_k * TILE_K + tj;   // reuse tj as column within K‑tile
        if (a_row < M && a_col < K) {
            As[ti][tj] = A[(b * M + a_row) * K + a_col];
        } else {
            As[ti][tj] = __float2half(0.0f);
        }

        // -------------------- load B tile --------------------
        int b_row = tile_k * TILE_K + ti;   // reuse ti as row within K‑tile
        int b_col = col;
        if (b_row < K && b_col < N) {
            Bs[ti][tj] = B[(b * K + b_row) * N + b_col];
        } else {
            Bs[ti][tj] = __float2half(0.0f);
        }

        __syncthreads();

        // -------------------- compute partial product --------------------
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            float a_val = __half2float(As[ti][kk]);
            float b_val = __half2float(Bs[kk][tj]);
            acc += a_val * b_val;
        }

        __syncthreads();
    }

    // -------------------- write result --------------------
    if (row < M && col < N) {
        C[(b * M + row) * N + col] = __float2half(acc);
    }
}
