cpp_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 16

// forward declaration of the kernel (defined in the CUDA source)
extern void bmm_fp16_kernel(const half*,
                            const half*,
                            half*,
                            int, int, int, int);

// ------------------------------------------------------------------
// C++ wrapper exposed to Python
// ------------------------------------------------------------------
torch::Tensor bmm_fp16_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Both inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "Both inputs must be half (fp16) tensors");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3,
                "Inputs must be 3‑D tensors (batch, M, K) and (batch, K, N)");
    TORCH_CHECK(A.size(0) == B.size(0),
                "Batch dimensions must match");
    TORCH_CHECK(A.size(2) == B.size(1),
                "Inner dimensions (K) must match");

    int batch = A.size(0);
    int M = A.size(1);
    int K = A.size(2);
    int N = B.size(2);

    auto C = torch::empty({batch, M, N}, A.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (M + TILE_M - 1) / TILE_M,
              batch);

    // launch kernel
    bmm_fp16_kernel<<<grid, block>>>(
        reinterpret_cast<const half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<half*>(C.data_ptr<at::Half>()),
        batch, M, N, K);

    // check for launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &bmm_fp16_forward, "Batched fp16 GEMM forward (CUDA)");
}
'''

# ----------------------------------------------------------------------
# Build the extension in‑line
# ----------------------------------------------------------------------
bmm_ext = load_inline(name='bmm_fp16_ext',
                      cpp_sources=cpp_src,
                      cuda_sources=cuda_src,
                      functions=['forward'],
                      verbose=False)

# ----------------------------------------------------------------------
# PyTorch Module that uses the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs batched matrix multiplication on fp16 tensors using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are contiguous and half‑precision
        A = A.contiguous()
        B = B.contiguous()
        return bmm_ext.forward(A, B)

# ----------------------------------------------------------------------
# Example usage (mirrors the reference script)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 128
    m = 128 * 4
    k = 256 * 4
    n = 512 * 4

    A = torch.rand(batch_size, m, k, dtype=torch.float16, device='cuda')
    B = torch.rand(batch_size, k, n, dtype=torch.float16, device='cuda')
    model = ModelNew()
    C = model(A, B)
    print(C.shape)   # should be (128, 512, 2048)
